import {createOffice} from './office-sim.js';
import {createOperations} from './operations.js';
import {createCampaign,levelsFromLegacy} from './campaign-levels.js';
export function cableID(l,byId){return `${l.a}:${byId[l.a].ports.indexOf(l.pa)}>${l.b}:${byId[l.b].ports.indexOf(l.pb)}`;}
export function createSharedWorld(ctx,network){
 const {nodes,links,byId,connect,refreshFaults,state}=ctx;let operations,office;
 const initial=links.slice();
 const configFor=p=>p.cfg??{admin:true,mode:'access',access:1,allowed:[1,70]};
 // Save format 31 (v31). Older saves (v29/v30, no format field) are migrated on load: the rack PDU
 // breaker table is added and derived device-logic state is rebuilt from the saved configuration.
 // Format 32 (v32) adds Campaign levels 0–10 (operations.levels/track) and rack input feeds. A v29–v31
 // campaign keeps its world and gets a levels record mapped from its contracts or rack projects.
 const SAVE_FORMAT=32;
 function migrate(data){const from=data.format||(data.operations?.version===1?30:29);if(from>=SAVE_FORMAT)return data;data=structuredClone(data);data.operations&&(data.operations.pdus??={});for(const d of data.physical||[])if(d.physical&&d.physical.powered===undefined)delete d.physical.powered;const o=data.operations;if(o){o.rackFeeds??={};if(o.mode==='campaign'&&!o.levels){o.legacyTrack=o.enterprise?'contracts':'projects';o.track='levels';o.emptySite=false;o.levels=levelsFromLegacy(o,data.office);}}data.format=SAVE_FORMAT;data.migratedFrom=from;return data;}
 function snapshot(includeRecovery=true){return {format:SAVE_FORMAT,office:office?.snapshot(),checkpoint:includeRecovery?operations?.checkpoint:null,operations:operations?.snapshot(),devices:nodes.filter(n=>n.spec).map(n=>n.spec),physical:nodes.map(n=>({id:n.id,physical:n.physical,ports:n.ports.map(p=>({optic:p.optic,fault:p.fault}))})),nets:network.snapshot(),cables:links.filter(l=>!l.retired).map(l=>({id:cableID(l,byId),a:l.a,b:l.b,pa:byId[l.a].ports.indexOf(l.pa),pb:byId[l.b].ports.indexOf(l.pb),kind:l.kind,tag:l.tag,speed:l.speed,custom:!!l.custom,unplugged:!!l.unplugged,looseEnd:l.looseEnd,media:l.media,length:l.length,label:l.label,fault:l.fault})),faults:{link:!!state.link,controller:!!state.controller,san:!!state.san,site:!!state.site,pending:false}};}
 function restore(data){if(!data)return;data=migrate(data);api.migratedFrom=data.migratedFrom||null;
 // LAN clients show the host's level evaluation (the host sees unredacted office data); solo/host evaluate locally.
 api.remoteCampaign=Array.isArray(data.campaign)?data.campaign:null;api.remoteSummary=data.campaignSummary||null;
 // Upgrade old MGMT-SW saves without shifting existing Ethernet cable indices.
 const hub=data.nets?.find(x=>x.id==='MGMT-SW');if(hub?.net.ports.length===54&&byId['MGMT-SW']?.ports.length===55){data=structuredClone(data);const row=data.nets.find(x=>x.id==='MGMT-SW');row.net.ports.splice(52,0,{admin:true,mode:'access',access:70,allowed:[1,70]});data.physical?.find(x=>x.id==='MGMT-SW')?.ports.splice(52,0,{});}
for(const r of data.operations?.racks||[])ctx.addRack?.(r);for(const d of data.devices||[])if(!byId[d.id])ctx.spawn(d);network.init();for(const n of nodes){n.physical=undefined;n.ports.forEach(p=>{p.optic=undefined;p.fault=undefined;});}for(const d of data.physical||[]){const n=byId[d.id];if(n){n.physical=structuredClone(d.physical);d.ports.forEach((p,i)=>Object.assign(n.ports[i]||{},p));}}network.restore(data.nets);for(const n of nodes)for(const p of n.ports)p.link=null;for(const l of links){l.unplugged=true;l.retired=true;l.looseEnd=null;}
 const existingLinks=new Map(links.map(l=>[cableID(l,byId),l]));for(const c of data.cables){const a=byId[c.a],b=byId[c.b];if(!a||!b||!a.ports[c.pa]||!b.ports[c.pb])continue;let l=existingLinks.get(c.id);if(!l){l=connect(c.a,c.b,c.kind,c.tag,c.speed,[a.ports[c.pa],b.ports[c.pb]]);l.custom=true;}Object.assign(l,{retired:false,looseEnd:c.looseEnd,media:c.media,length:c.length,label:c.label,fault:c.fault});l.unplugged=c.unplugged;if(!l.unplugged){l.pa.link=l;l.pb.link=l;}else {if(l.pa.link===l)l.pa.link=null;if(l.pb.link===l)l.pb.link=null;if(c.looseEnd==='a')l.pb.link=l;if(c.looseEnd==='b')l.pa.link=l;}}
 Object.assign(state,data.faults,{pending:false});operations?.restore(data.operations,data.checkpoint);office?.restore(data.office);operations?.repair();refreshFaults();network.logic?.touch();}
 function apply(action,actor,players,permissions={isHost:true}){api.remoteCampaign=null;const result=applyAction(action,actor,players,permissions);const done=r=>{operations.settle?.();network.logic?.touch();return r;};return result&&typeof result.then==='function'?result.then(done):done(result);}
 function applyAction(action,actor,players,permissions={isHost:true}){if(action.type!=='engineering'&&operations.game.stock.some(s=>s.holders.includes(actor||'ENGINEER-01')))throw Error('Finish this task or put the item down first');if(action.type==='office')return office.apply(action.action,actor,permissions.isHost===true);if(action.type==='engineering'){const result=operations.apply(action.action,actor,players);if(action.action.type==='mode'&&!action.action.resume)office.reset(action.action.mode==='campaign'?'campaign':'free');return result;}if(action.type==='config')return network.apply(action.action);
 if(action.type==='campaign')return campaign.apply(action.action||{},actor);
 if(action.type==='reset-cables'){for(const n of nodes)for(const p of n.ports)p.link=null;for(const l of links)l.unplugged=true;for(const l of initial){l.unplugged=false;l.pa.link=l;l.pb.link=l;}refreshFaults();return 'Original cabling restored';}
 if(action.type==='cable'){const l=links.find(l=>cableID(l,byId)===action.id);if(!l||l.pa.medium==='Internal'||l.pb.medium==='Internal')throw new Error('Cable unavailable');if(action.unplugged){l.unplugged=true;if(l.pa.link===l)l.pa.link=null;if(l.pb.link===l)l.pb.link=null;}else{if(l.pa.link&&l.pa.link!==l||l.pb.link&&l.pb.link!==l)throw new Error('Port occupied');l.unplugged=false;l.pa.link=l;l.pb.link=l;}refreshFaults();return l.unplugged?'Cable unplugged':'Cable reconnected';}
 if(action.type==='connect'){const a=byId[action.a],b=byId[action.b],pa=a?.ports[action.pa],pb=b?.ports[action.pb];if(!pa||!pb||a===b||pa.link||pb.link||pa.service||pb.service||pa.medium==='Internal'||pa.medium==='Console'||pa.medium!==pb.medium||pa.speed!==pb.speed)throw new Error('Choose compatible free data ports');if(a.type==='san'&&b.type==='san')throw new Error('Keep SAN fabrics isolated');const existing=links.find(l=>l.a===a.id&&l.b===b.id&&l.pa===pa&&l.pb===pb);if(existing){existing.unplugged=false;pa.link=existing;pb.link=existing;}else{if(links.length>400)throw new Error('Cable limit reached; reuse an unplugged cable');const l=connect(a.id,b.id,pa.medium==='Fibre Channel'?'storage':'application','lab',Math.min(pa.speed,pb.speed),[pa,pb]);l.custom=true;}pa.cfg=configFor(pa);pb.cfg=configFor(pb);refreshFaults();return 'Ports connected';}
 throw new Error('Unknown world action');}
 const api={snapshot,restore,apply};operations=createOperations(ctx,api,network);api.operations=operations;office=createOffice(ctx,api,network);api.office=office;const campaign=createCampaign(api,network,ctx);api.campaign=campaign;const officeTick=office.tick;office.tick=now=>{const a=officeTick(now),b=campaign.tick(now);return a||b;};network.setOffice?.(office);network.logic?.setWorld(api,ctx);office.preconfigure();api.snapshotFor=()=>{const data=snapshot(false);data.office=office.snapshot(true);if(operations.game.track==='levels'&&operations.game.levels)data.campaign=campaign.evaluate(true);data.campaignSummary=operations.campaignSummary();return data;};operations.initialize();return api;
}
